import sys

s = sys.stdin.read().split()[0]
n = len(s)
found = set()
for i in range(n):
    for j in range(i + 1, n + 1):
        t = s[i:j]
        if all(t[k] == t[len(t) - 1 - k] for k in range(len(t))):
            found.add(t)
print('\n'.join(sorted(found)))

